<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {mergeRequirementDraft,isStaleDraft,syncDocumentSelection,type RequirementDraft} from '../caseflowDrafts'
import {contentChanged,needsGroundingAcknowledgement,groundingLabel} from '../caseflowGrounding'
import GroundingReport from './GroundingReport.vue'
import WorkflowGuide from './WorkflowGuide.vue'
import ChangeReview from './ChangeReview.vue'
import KnowledgeLibrary from './KnowledgeLibrary.vue'
import DocumentReader from './DocumentReader.vue'
import {parseSourceRoute} from '../caseflowSources'
import {nextStep,unreadDocuments,updatedDrafts,currentDocuments} from '../caseflowWorkflow'
const projects=ref<any[]>([]),p=ref<any>(null),tab=ref('需求'),busy=ref(false),error=ref(''),notice=ref(''),name=ref('')
const body=ref(''),docName=ref('需求说明'),role=ref('requirement'),previous=ref(''),docs=ref<string[]>([]),reqs=ref<string[]>([]),cases=ref<string[]>([]),consent=ref(false)
const sourceUrl=ref('')
const drafts=ref<Record<string,RequirementDraft>>({}),editor=ref<any>(null),steps=ref(''),review=ref(''),batchNote=ref(''),filter=ref('all'),source=ref<any>(null),changes=ref<Record<string,string[]>>({})
const settings=ref<any>(null),settingsInfo=ref<any>(null),settingsVisible=ref(false),tasks=ref<any[]>([]),progress=ref(''),trace=ref<any[]>([])
const runName=ref('本次测试'),runCase=ref(''),runStatus=ref('未执行'),runNote=ref('')
const manualText=ref(''),manualDoc=ref(''),manualPage=ref(1),manualQuote=ref('')
const ruleName=ref(''),ruleMetric=ref(''),ruleUnit=ref('元'),ruleKind=ref('discount'),ruleMin=ref(''),ruleMax=ref(''),ruleThreshold=ref(''),ruleDiscount=ref(''),ruleIds=ref<string[]>([]),ruleConfirmed=ref(false)
const groundingAck=ref(false),batchGroundingAck=ref(false)
const importExpanded=ref(false),scopeExpanded=ref(false),showConfirmed=ref(false),showHistoryDocs=ref(false)
const visibleProjects=computed(()=>projects.value.filter(x=>!x.archived)),archivedProjects=computed(()=>projects.value.filter(x=>x.archived))
const editorDirty=computed(()=>!!editor.value&&contentChanged(s.value?.cases.find((c:any)=>c.id===editor.value.id),editor.value,steps.value.split('\n').filter(t=>t.trim())))
const editorNeedsAck=computed(()=>needsGroundingAcknowledgement(editor.value,editorDirty.value))
const batchNeedsAck=computed(()=>cases.value.some(id=>needsGroundingAcknowledgement(s.value?.cases.find((c:any)=>c.id===id))))
const clarifyQuestion=ref(''),clarifyKind=ref('ambiguity'),clarifyIds=ref<string[]>([]),clarifyAnswers=ref<Record<string,string>>({})
const s=computed(()=>p.value?.state),active=computed(()=>tasks.value.find(t=>['queued','running'].includes(t.status)))
const shown=computed(()=>s.value?.cases.filter((c:any)=>filter.value==='all'||(filter.value==='applied'?!!c.applied_to:c.status===filter.value&&!c.applied_to))??[])
const clarifications=computed(()=>s.value?.clarifications??[])
const pending=computed(()=>s.value?.changes.filter((c:any)=>c.status==='pending')??[])
const workflow=computed(()=>nextStep(s.value,tasks.value))
const updatedRules=computed(()=>s.value?updatedDrafts(s.value):[])
const visibleRequirements=computed(()=>s.value?.requirements.filter((r:any)=>r.status==='draft'||showConfirmed.value)??[])
const scopeDocuments=computed(()=>showHistoryDocs.value?s.value.documents:currentDocuments(s.value))
const unreadSelected=computed(()=>s.value?unreadDocuments(s.value,tasks.value).filter(d=>docs.value.includes(d.id)):[])
let timer:ReturnType<typeof setTimeout>|undefined,stream:EventSource|null=null,disposed=false
const status=(v:string)=>({draft:'待审核',confirmed:'已确认',excluded:'已排除',approved:'已审核',rejected:'已驳回',needs_review:'待复审',queued:'等待处理',running:'处理中',completed:'已完成',failed:'未完成',blocked:'已停止',accepted:'已接受'} as Record<string,string>)[v]??v
const kind=(v:string)=>({unchanged:'内容未变，确认来源',added:'新增需求',possible_change:'可能修改或拆分合并',possibly_removed:'可能删除或被合并'} as Record<string,string>)[v]??v
const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
const path=()=>'/projects/'+p.value.id
async function api(url:string,value?:unknown){const response=await fetch('/api/v1/caseflow'+url,value===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});const result=await response.json();if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'输入未通过检查');return result}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function use(value:any){if(p.value?.id===value.id&&p.value.revision>value.revision)return;const before=p.value?.id===value.id?p.value.state.documents.map((d:any)=>d.id):undefined;if(before&&value.state.documents.some((d:any)=>!before.includes(d.id)))consent.value=false;docs.value=syncDocumentSelection(value.state.documents,docs.value,before);p.value=value;cases.value=cases.value.filter(id=>value.state.cases.some((c:any)=>c.id===id&&!c.applied_to));for(const r of value.state.requirements)drafts.value[r.id]=mergeRequirementDraft(drafts.value[r.id],r.text);reqs.value=reqs.value.filter(id=>value.state.requirements.some((r:any)=>r.id===id&&r.status==='confirmed'));for(const c of value.state.changes)if(!changes.value[c.id])changes.value[c.id]=c.old_ids.length===1?c.old_ids.slice():[]}
function tabLabel(t:string){return t==='需求'?'资料与知识':t==='用例'?'检查清单':t==='变更'?'需求更新':t}
async function goNext(target=workflow.value.target){
 const page=['changes','updated'].includes(target)?'变更':['review','drafts','export'].includes(target)?'用例':'需求';navigate(page)
 if(target==='import')importExpanded.value=true
 if(target==='scope'||target==='generate')scopeExpanded.value=true
 if(target==='generate')showConfirmed.value=true
 if(target==='review')filter.value='needs_review'
 if(target==='drafts')filter.value='draft'
 const anchors:Record<string,string>={import:'workflow-import',scope:'workflow-scope',requirements:'workflow-requirements',generate:'workflow-requirements',changes:'workflow-changes',updated:'workflow-updated',clarify:'workflow-clarify',review:'workflow-cases',drafts:'workflow-cases',export:'workflow-cases'}
 await nextTick();document.getElementById(anchors[target]??'')?.scrollIntoView({block:'start',behavior:'smooth'})
}
async function archiveProject(x:any,archived:boolean){await act(async()=>{await api('/projects/'+x.id+'/archive',{revision:x.revision,archived});await list();notice.value=archived?'项目已归档，可从归档项目找回。':'项目已恢复。'})}
function navigate(t:string){tab.value=t;if(p.value)window.location.hash='/projects/'+p.value.id+'/'+(t==='用例'?'cases':t==='变更'?'changes':'knowledge');void nextTick(()=>window.scrollTo({top:0,behavior:'auto'}))}
async function refresh(){const id=p.value?.id;if(!id)return;const value=await api('/projects/'+id);if(p.value?.id===id)use(value)}
async function list(){projects.value=await api('/projects')}
function reset(){stream?.close();if(timer)clearTimeout(timer);drafts.value={};docs.value=[];reqs.value=[];cases.value=[];trace.value=[];tasks.value=[];tab.value='需求';consent.value=false;progress.value='';importExpanded.value=false;scopeExpanded.value=false;showConfirmed.value=false;showHistoryDocs.value=false;editor.value=null;source.value=null;previous.value='';runCase.value='';clarifyIds.value=[];clarifyQuestion.value='';clarifyAnswers.value={};manualText.value='';manualDoc.value='';manualPage.value=1;manualQuote.value='';ruleIds.value=[];ruleConfirmed.value=false;groundingAck.value=false;batchGroundingAck.value=false;ruleName.value='';ruleMetric.value='';ruleUnit.value='元';ruleKind.value='discount';ruleMin.value='';ruleMax.value='';ruleThreshold.value='';ruleDiscount.value=''}
async function open(id:string){await act(async()=>{reset();use(await api('/projects/'+id));localStorage.setItem('caseflow-project',id);await loadTasks();navigate('需求')})}
async function home(){await act(async()=>{reset();p.value=null;localStorage.removeItem('caseflow-project');window.location.hash='';await list()})}
async function create(){await act(async()=>{reset();use(await api('/projects',{name:name.value}));name.value='';localStorage.setItem('caseflow-project',p.value.id);navigate('需求');await list()})}
async function saveText(){await act(async()=>{use(await api(path()+'/texts',{revision:p.value.revision,name:docName.value,content:body.value,role:role.value,previous_id:previous.value||null,source_url:sourceUrl.value}));body.value='';previous.value='';consent.value=false;importExpanded.value=false;scopeExpanded.value=true;notice.value='资料已保存。下一步：在下方允许处理所选资料，再点击“读取需求”。';void goNext('scope')})}
async function upload(e:Event,result=false){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await act(async()=>{const form=new FormData();form.append('file',file);form.append('revision',p.value.revision);if(result){form.append('name',runName.value);form.append('request_id',crypto.randomUUID())}else{form.append('role',role.value);form.append('source_url',sourceUrl.value);if(previous.value)form.append('previous_id',previous.value)}const response=await fetch('/api/v1/caseflow'+path()+(result?'/runs/import':'/files'),{method:'POST',body:form});const value=await response.json();if(!response.ok)throw new Error(value.detail);use(value);previous.value='';consent.value=false;if(!result){importExpanded.value=false;scopeExpanded.value=true;void goNext('scope')};notice.value=result?'执行结果已导入。':'资料已导入。下一步：允许处理所选资料，再点击“读取需求”。'});input.value=''}
function original(d:any,page?:number){source.value={documentId:d.id,legacy:page?{page}:undefined};window.location.hash='/projects/'+p.value.id+'/documents/'+d.id}
function citation(q:any){source.value={documentId:q.document_id,evidenceId:q.evidence_id,legacy:q.evidence_id?undefined:{page:q.page,quote:q.quote}};window.location.hash='/projects/'+p.value.id+'/documents/'+q.document_id+(q.evidence_id?'?evidence='+q.evidence_id:'')}
function citationLabel(q:any){const d=s.value.documents.find((d:any)=>d.id===q.document_id);return d?.format==='pdf'?'第'+q.page+'页':d?.format&&d.format!=='legacy_text'?'段落定位':'历史文本段'+q.page}
function closeSource(){source.value=null;navigate(tab.value)}
function located(id:string){if(!source.value)return;source.value={...source.value,evidenceId:id,legacy:undefined};history.replaceState(null,'','#/projects/'+p.value.id+'/documents/'+source.value.documentId+'?evidence='+id)}
async function applyRoute(){const hash=window.location.hash,r=parseSourceRoute(hash);if(!r)return;if(p.value?.id!==r.projectId){source.value=null;const value=await api('/projects/'+r.projectId);if(window.location.hash!==hash)return;reset();use(value);localStorage.setItem('caseflow-project',r.projectId);await loadTasks()};if(r.documentId){if(source.value?.documentId!==r.documentId||r.evidenceId)source.value={documentId:r.documentId,evidenceId:r.evidenceId}}else{source.value=null;tab.value=r.tab??'需求'}}
let routePending=false
function hashChanged(){if(busy.value){routePending=true;return}void act(applyRoute)}
watch(busy,value=>{if(!value&&routePending){routePending=false;void act(applyRoute)}})
async function addManual(){await act(async()=>{use(await api(path()+'/requirements',{revision:p.value.revision,text:manualText.value,document_id:manualDoc.value,page:manualPage.value,quote:manualQuote.value}));manualText.value='';manualQuote.value='';notice.value='补充需求已保存为草稿，请核对后确认。'})}
async function addClarification(){await act(async()=>{use(await api(path()+'/clarifications',{revision:p.value.revision,question:clarifyQuestion.value,kind:clarifyKind.value,requirement_ids:clarifyIds.value}));clarifyQuestion.value='';clarifyIds.value=[];notice.value='问题已登记，关联需求需要澄清后重新确认。'})}
async function resolveClarification(q:any){await act(async()=>{use(await api(path()+'/clarifications/'+q.id,{revision:p.value.revision,answer:clarifyAnswers.value[q.id]??''}));notice.value='处理决定已保存，请核对关联需求内容并重新确认。'})}
async function saveReq(r:any,state:string){await act(async()=>{const d=drafts.value[r.id]!;if(isStaleDraft(d,r.text))throw new Error('这条需求已有新内容，请先核对并处理下方编辑冲突');use(await api(path()+'/requirements/'+r.id,{revision:p.value.revision,text:d.text,status:state,answer:d.answer}));drafts.value[r.id]=mergeRequirementDraft(undefined,s.value.requirements.find((v:any)=>v.id===r.id).text);notice.value='需求已保存。'})}
async function start(type:string,existing?:any){await act(async()=>{if(!consent.value)throw new Error('请先选择资料并勾选允许处理');if(type==='review'){caseFresh(existing);if(editorDirty.value)throw new Error('请先保存草稿，再检查已保存内容')};const selected=type==='extract'?unreadSelected.value.map(d=>d.id):docs.value;if(!selected.length)throw new Error(type==='extract'?'所选资料已经读取，请继续确认规则或添加更新资料':'请选择本轮处理资料');const key='caseflow-pending:'+p.value.id;if(localStorage.getItem(key)){await loadTasks();if(localStorage.getItem(key))throw new Error('上次提交结果尚未找回，请刷新查看处理记录，避免重复生成。')};const request_id=crypto.randomUUID();localStorage.setItem(key,request_id);try{const task=await api(path()+'/tasks',{revision:p.value.revision,request_id,kind:type,document_ids:selected,requirement_ids:type==='review'?existing.requirement_ids:type==='generate'?reqs.value:[],case_ids:type==='review'?[existing.id]:[],consent:true});localStorage.removeItem(key);tasks.value.unshift(task);if(type==='review')editor.value=null;follow(task)}catch(e){await loadTasks();throw e}})}
async function resumeTask(t:any){await act(async()=>{const result=await api('/tasks/'+t.id+'/resume',{revision:p.value.revision});await loadTasks();follow(result)})}
async function loadTasks(){const id=p.value?.id;if(!id)return;const result=await api('/projects/'+id+'/tasks');if(p.value?.id!==id)return;tasks.value=result;const key='caseflow-pending:'+id;if(tasks.value.some(t=>t.request_id===localStorage.getItem(key)))localStorage.removeItem(key);if(active.value)follow(active.value)}
function follow(t:any){stream?.close();if(timer)clearTimeout(timer);stream=new EventSource('/api/v1/caseflow/tasks/'+t.id+'/events?after='+(localStorage.getItem('cf-cursor:'+t.id)??'0'));stream.onmessage=e=>{if(/^\d+$/.test(e.lastEventId))localStorage.setItem('cf-cursor:'+t.id,e.lastEventId);try{const item=JSON.parse(e.data);progress.value=item.payload?.message??'';if(item.kind==='tool')trace.value.push(item.payload)}catch{}};stream.onerror=()=>progress.value='正在重新连接，已保存任务仍可查询';void poll()}
async function poll(){const id=p.value?.id;if(disposed||!id)return;try{const result=await api('/projects/'+id+'/tasks');if(disposed||p.value?.id!==id)return;tasks.value=result;if(active.value)timer=setTimeout(poll,1500);else{stream?.close();await refresh();if(disposed||p.value?.id!==id)return;if(tasks.value[0]?.error)error.value=tasks.value[0].error;else notice.value=tasks.value[0]?.result?.message??'处理完成，请审核结果。';progress.value='';const done=tasks.value[0];if(done?.status==='completed'){if(done.kind==='review'){const checked=s.value.cases.find((c:any)=>c.id===done.input?.case_ids?.[0]);if(checked&&!editor.value)edit(checked);else if(checked&&editor.value?.id===checked.id&&!editorDirty.value)edit(checked)}else if(done.kind==='extract'){scopeExpanded.value=false;void goNext(pending.value.length?'changes':'requirements')}else if(done.kind==='generate'){navigate('用例');filter.value='all'}}}}catch{if(!disposed&&p.value?.id===id)timer=setTimeout(poll,2500)}}
function caseFresh(c:any){const saved=s.value.cases.find((v:any)=>v.id===c.id);if(saved?.revision!==c.revision)throw new Error('这条用例已有新修改，请重新打开并核对；本次编辑仍保留在窗口中');if(JSON.stringify(saved?.grounding)!==JSON.stringify(c.grounding))throw new Error('这条用例的依据检查已更新，请重新打开核对；本次编辑仍保留在窗口中')}
function reconcile(r:any,keep:boolean){const draft=drafts.value[r.id]!;drafts.value[r.id]={text:keep?draft.text:r.text,answer:draft.answer,baseText:r.text}}
function fieldDiff(before:any,after:any){const fields:Record<string,string>={text:'需求内容',title:'标题',preconditions:'前置条件',data:'输入数据',steps:'操作步骤',expected:'预期结果',status:before?.text!==undefined?'确认状态':'审核状态',requirement_revisions:'关联需求修订'};return Object.entries(fields).filter(([key])=>JSON.stringify(before?.[key])!==JSON.stringify(after?.[key])).map(([key,label])=>({label,before:formatField(key,before?.[key],before),after:formatField(key,after?.[key],after)}))}
function formatField(key:string,value:any,row:any):string{if(value===undefined)return '—';if(key==='status')return row?.applied_to?'已应用':(row?.text!==undefined&&value==='draft'?'待确认':status(value));if(key==='requirement_revisions')return Object.entries(value??{}).map(([id,rev])=>(s.value.requirements.find((r:any)=>r.id===id)?.code??id)+' · 修订 '+rev).join('、');return Array.isArray(value)?value.join('\n'):String(value)}
function historyAfter(h:any,index:number){return s.value.history.slice(index+1).find((v:any)=>v.kind===h.kind&&v.id===h.id)?.value??(h.kind==='case'?s.value.cases:s.value.requirements).find((v:any)=>v.id===h.id)}
function edit(c:any){editor.value=JSON.parse(JSON.stringify(c));steps.value=c.steps.join('\n');review.value=c.review_note??'';groundingAck.value=false}
async function saveCase(state:string){await act(async()=>{const c=editor.value;caseFresh(c);use(await api(path()+'/cases/'+c.id,{revision:p.value.revision,title:c.title,preconditions:c.preconditions,data:c.data,steps:steps.value.split('\n').filter(t=>t.trim()),expected:c.expected,status:state,review_note:review.value,acknowledge_grounding:groundingAck.value}));editor.value=null;notice.value='用例已保存。'})}
async function applyProposal(){await act(async()=>{const c=editor.value;caseFresh(c);use(await api(path()+'/cases/'+c.id,{revision:p.value.revision,title:c.title,preconditions:c.preconditions,data:c.data,steps:steps.value.split('\n').filter(t=>t.trim()),expected:c.expected,status:'draft',review_note:review.value}));use(await api(path()+'/proposals/'+c.id,{revision:p.value.revision}));editor.value=null;notice.value='建议已应用到原用例并保存为草稿，请审核。'})}
async function batch(state:string){await act(async()=>{use(await api(path()+'/reviews',{revision:p.value.revision,ids:cases.value,status:state,review_note:batchNote.value,acknowledge_grounding:batchGroundingAck.value}));cases.value=[];batchNote.value='';batchGroundingAck.value=false;notice.value='审核结果已保存。'})}
async function addNumericRule(){await act(async()=>{use(await api(path()+'/numeric-rules',{revision:p.value.revision,name:ruleName.value,metric:ruleMetric.value,unit:ruleUnit.value,kind:ruleKind.value,minimum:ruleMin.value,maximum:ruleMax.value,threshold:ruleThreshold.value,discount:ruleDiscount.value,requirement_ids:ruleIds.value,confirmed:ruleConfirmed.value}));ruleConfirmed.value=false;notice.value='数值规则已保存，关联旧用例需要复审。'})}
async function disableNumericRule(id:string){await act(async()=>{use(await api(path()+'/numeric-rules/'+id+'/disable',{revision:p.value.revision}));notice.value='规则已停用，历史记录仍保留。'})}
async function decide(c:any,action:string){await act(async()=>{use(await api(path()+'/changes/'+c.id,{revision:p.value.revision,action,target_ids:['add','reject'].includes(action)?[]:changes.value[c.id]??[]}));notice.value=action==='replace'?'修改已保存。请在本页核对并确认新规则。':'这项决定已保存，继续核对下一项。';if(action==='replace')void goNext('updated')})}
async function strategy(e:Event){await act(async()=>{use(await api(path()+'/strategy',{revision:p.value.revision,mode:(e.target as HTMLSelectElement).value}));consent.value=false})}
async function showSettings(){settingsVisible.value=true;await act(async()=>{settingsInfo.value=await api('/settings');settings.value=JSON.parse(JSON.stringify(settingsInfo.value.settings))})}
async function saveSettings(){await act(async()=>{settingsInfo.value=await api('/settings',settings.value);notice.value='设置已保存。';consent.value=false})}
async function record(){await act(async()=>{const c=s.value.cases.find((c:any)=>c.id===runCase.value);if(!c)throw new Error('请选择已审核用例');use(await api(path()+'/runs',{revision:p.value.revision,request_id:crypto.randomUUID(),name:runName.value,results:[{case_id:c.id,revision:c.revision,status:runStatus.value,note:runNote.value}]}));runNote.value='';notice.value='实际执行结果已记录。'})}
function escape(e:KeyboardEvent){if(e.key==='Escape'){if(source.value)closeSource();else if(editor.value)editor.value=null;else settingsVisible.value=false}if(e.key==='Tab'&&(source.value||editor.value||settingsVisible.value)){const dialogs=Array.from(document.querySelectorAll('.cf .dialog'));const dialog=source.value?document.querySelector('.cf .source-overlay .dialog'):dialogs[dialogs.length-1];const targets=Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select,textarea,summary,a[href]')??[]);const first=targets[0],last=targets[targets.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
let previousFocus:HTMLElement|null=null
watch(()=>JSON.stringify([editor.value?.title,editor.value?.preconditions,editor.value?.data,editor.value?.expected,steps.value]),()=>groundingAck.value=false)
watch(()=>JSON.stringify([cases.value,p.value?.revision]),()=>batchGroundingAck.value=false)
watch(()=>JSON.stringify([ruleName.value,ruleMetric.value,ruleUnit.value,ruleKind.value,ruleMin.value,ruleMax.value,ruleThreshold.value,ruleDiscount.value,ruleIds.value]),()=>ruleConfirmed.value=false)
watch(()=>!!(source.value||editor.value||settingsVisible.value),async opened=>{if(opened){previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.cf .dialog button')?.focus()}else previousFocus?.focus()})
onMounted(async()=>{window.addEventListener('keydown',escape);window.addEventListener('hashchange',hashChanged);await act(async()=>{await list();if(window.location.hash){await applyRoute();return};const id=localStorage.getItem('caseflow-project');if(id&&projects.value.some(x=>x.id===id&&!x.archived)){reset();use(await api('/projects/'+id));await loadTasks()}})})
onUnmounted(()=>{disposed=true;stream?.close();if(timer)clearTimeout(timer);window.removeEventListener('keydown',escape);window.removeEventListener('hashchange',hashChanged)})
</script>
<template>
<div class="cf"><aside><button class="brand" @click="home" :disabled="busy"><b>C</b><span>CaseFlow<small>需求与测试用例工作台</small></span></button><button class="home" @click="home" :disabled="busy">▦　我的项目</button><template v-if="p"><p class="project-name">{{p.name}}</p><nav aria-label="项目导航"><button v-for="t in ['需求','用例','变更']" :key="t" :class="{active:tab===t}" @click="navigate(t)">{{tabLabel(t)}}<small v-if="t==='变更'&&pending.length">{{pending.length}}</small></button></nav></template><div class="aside-bottom"><button @click="showSettings">⚙　设置</button><small>资料有依据，变更可跟踪</small></div></aside>
<main><header><span>{{p?p.name:'我的项目'}} <span class="muted" v-if="p"> / {{tabLabel(tab)}}</span></span><small class="local">● 本机工作台</small></header><div class="content"><p v-if="error" class="message error" role="alert">{{error}} <button @click="error=''" aria-label="关闭错误">×</button></p><p v-if="notice" class="message success" role="status">{{notice}}</p>
<template v-if="!p">
<div class="title"><div><small class="eyebrow">CASEFLOW</small><h1>把需求变成可执行的检查清单</h1><p>使用自己的需求资料，整理规则、审核清单，再导出交付。</p></div></div>
<form class="card create" @submit.prevent="create"><div><h2>新建项目</h2><p class="muted">创建后即可粘贴需求，或导入已有文档。</p></div><div class="inline"><input v-model="name" aria-label="项目名称" placeholder="输入项目名称" maxlength="100" required><button class="primary" :disabled="busy||!name.trim()">创建并开始 →</button></div></form>
<div class="heading" v-if="visibleProjects.length"><h2>我的项目</h2><small>{{visibleProjects.length}} 个</small></div><div class="project-grid"><article class="card project" v-for="x in visibleProjects" :key="x.id"><button class="project-open" @click="open(x.id)"><span class="folder">▤</span><h3>{{x.name}}</h3><p>{{x.summary.confirmed}} 条已确认规则 · {{x.summary.approved}} 条已审核检查项</p><small>更新于 {{date(x.updated_at)}}</small><span class="arrow">↗</span></button><details class="project-menu"><summary>项目管理</summary><button class="text-button" @click="archiveProject(x,true)" :disabled="busy">归档项目</button></details></article></div>
<div v-if="!visibleProjects.length" class="card home-empty"><h2>从你的需求开始</h2><p>创建项目后，添加要检查的功能和业务规则。系统将显示当前进度，并告诉你下一步。</p><p class="muted">支持文字、Word、文本PDF、Markdown和TXT。</p></div>
<details v-if="archivedProjects.length" class="archived-projects"><summary>归档项目 · {{archivedProjects.length}}</summary><p class="muted">资料和历史保留，恢复后可继续使用。</p><div class="archived-row" v-for="x in archivedProjects" :key="x.id"><span>{{x.name}}</span><button class="text-button" @click="archiveProject(x,false)" :disabled="busy">恢复项目</button></div></details>
</template>
<template v-else-if="s"><p v-if="s.example" class="message">这是预置示例，包含人工编写的需求和用例，非模型生成结果。可先确认需求，体验审核与导出；真实资料请新建项目。</p><div class="title"><div><h1>{{tab==='需求'?'资料与知识':tab==='用例'?'审核与交付检查清单':'确认需求更新'}}</h1><p>{{tab==='需求'?'添加需求后，按页面提示确认规则并生成检查清单。':tab==='用例'?'生成供人工执行的检查清单，审核后导出；实际执行结果单独记录。':'逐项核对修改建议，保留已经确认的工作。'}}</p></div><button class="secondary" @click="act(refresh)" :disabled="busy">刷新</button></div><WorkflowGuide :next="workflow" @proceed="goNext()"/><p v-if="active" class="progress" role="status">◌ {{progress||'正在处理所选资料，离开页面后仍可查询。'}}</p>
<template v-if="tab==='需求'"><KnowledgeLibrary :project-id="p.id" :revision="p.revision" @read="original"/><details class="card import-panel" id="workflow-import" :open="!s.documents.length||importExpanded"><summary>添加或更新需求资料</summary><div class="heading"><h2>添加资料</h2><small>支持 Word、文本 PDF、Markdown 和 TXT</small></div><label v-if="s.documents.length">这份资料用于<select v-model="previous"><option value="">添加新的需求资料</option><option v-for="d in currentDocuments(s).filter((d:any)=>d.role===role)" :key="d.id" :value="d.id">更新：{{d.name}}</option></select></label><label for="cf-text">直接粘贴需求</label><textarea id="cf-text" v-model="body" rows="4" placeholder="描述业务规则、操作条件和期望结果。暂时不清楚的规则也可以先记录。"></textarea><div class="actions"><button class="primary" @click="saveText" :disabled="busy||!!active||!body.trim()">保存并继续 →</button><label class="upload secondary">上传文件<input type="file" accept=".md,.txt,.pdf,.docx" @change="upload($event)" :disabled="busy||!!active"></label><small class="muted">每份最多 5 MiB；上传后请核对解析内容。</small></div><details class="detail"><summary>资料名称与用途</summary><div class="inline wrap"><label>资料名称<input v-model="docName"></label><label>来源网址（可选）<input v-model="sourceUrl" type="url" maxlength="2000" placeholder="https://…（只记录，不自动抓取）"></label><label>资料用途<select v-model="role" @change="previous=''"><option value="requirement">需求说明</option><option value="context">补充参考</option></select></label></div></details></details>
<details class="card scope-panel" id="workflow-scope" v-if="s.documents.length" :open="scopeExpanded"><summary>本次使用的资料 · {{docs.length}} 份已选择</summary><div class="heading"><h2>选择资料</h2><small>{{docs.length}} 份已选择</small></div><div class="document" v-for="d in scopeDocuments" :key="d.id"><label class="check"><input type="checkbox" v-model="docs" :value="d.id" @change="consent=false"><span><strong>{{d.name}}</strong><small>{{d.role==='requirement'?'需求说明':'补充参考'}} · {{d.format==='pdf'?d.pages.length+'页':d.format&&d.format!=='legacy_text'?'按段落定位':d.pages.length+'个历史文本段'}} · {{date(d.created_at)}}<span v-if="d.previous_id"> · 更新资料</span><span v-if="s.documents.some((x:any)=>x.previous_id===d.id)"> · 历史资料</span></small></span></label><div><p v-for="warning in d.warnings??[]" :key="warning" class="error-text">{{warning}}</p><button class="text-button" @click="original(d)">查看原文</button></div></div><label v-if="s.documents.some((d:any)=>d.previous_id)" class="check"><input type="checkbox" v-model="showHistoryDocs">显示历史资料</label><label class="check consent"><input type="checkbox" v-model="consent">允许将所选资料发送给已配置的模型进行处理。</label><div class="actions"><button class="primary" @click="start('extract')" :disabled="busy||!!active||!consent||!unreadSelected.length">{{unreadSelected.length?'读取需求':'所选需求已读取'}}</button><details><summary>资料检索选项</summary><label>选取方式<select :value="s.retrieval_mode??'keyword'" @change="strategy"><option value="keyword">关键词</option><option value="vector">语义检索</option><option value="hybrid">关键词与语义</option><option value="rerank">混合检索并排序</option></select></label><button class="secondary" @click="start('index')" :disabled="busy||!!active||!consent">建立资料索引</button><p class="muted">语义检索和排序需要有效模型额度，不会自动降级。</p></details></div></details>
<section class="card" id="workflow-requirements" v-if="s.documents.length"><div class="heading"><h2>确认规则</h2><small>{{s.summary.confirmed}} 条已确认</small></div><p class="muted">核对规则是否符合原文，再确认。生成清单时勾选已确认的规则，每批最多3条。</p><button v-if="s.requirements.some((r:any)=>r.status!=='draft')" class="text-button" @click="showConfirmed=!showConfirmed">{{showConfirmed?'只看待确认规则':'查看已确认与已排除规则'}}</button><p v-if="!s.requirements.length" class="empty">添加资料并整理后，在这里核对每条需求。</p><article class="requirement" v-for="r in visibleRequirements" :key="r.id"><div class="item-title"><label class="check"><input type="checkbox" v-model="reqs" :value="r.id" :disabled="r.status!=='confirmed'"><strong>{{r.code}}</strong></label><span class="badge" :class="r.status">{{r.status==='draft'?'待确认':status(r.status)}}</span><small class="muted">{{r.origin==='explicit'?'原文明示':'用户确认补充'}}</small></div><textarea :aria-label="r.code+'需求内容'" v-model="drafts[r.id]!.text" rows="2"></textarea><div v-if="isStaleDraft(drafts[r.id]!,r.text)" class="message error"><p>这条需求已更新，你的编辑已保留。当前保存内容：{{r.text}}</p><button @click="reconcile(r,false)">使用当前内容</button><button @click="reconcile(r,true)">核对后保留我的编辑</button></div><div class="citations"><button v-for="(q,i) in r.citations" :key="String(i)" @click="citation(q)">查看依据 · {{citationLabel(q)}}</button></div><div class="questions" v-if="r.questions.length"><strong>需要澄清</strong><p v-for="q in r.questions" :key="q">{{q}}</p><input v-model="drafts[r.id]!.answer" :aria-label="r.code+'澄清回答'" placeholder="填写已确定的规则；未知时可以暂不回答"></div><details v-if="r.answers.length"><summary>已确认的补充</summary><p v-for="(a,i) in r.answers" :key="String(i)">{{a.text}}</p></details><div class="actions"><button class="primary" @click="saveReq(r,'confirmed')" :disabled="busy||!!active">确认需求</button><button class="secondary" @click="saveReq(r,'draft')" :disabled="busy||!!active">保存草稿</button><button class="text-button" @click="saveReq(r,'excluded')" :disabled="busy||!!active">排除</button></div></article><div class="bottom" v-if="s.requirements.length"><details class="detail" :open="!!reqs.length&&!consent"><summary>生成使用的资料 · {{docs.length}} 份已选择</summary><label class="check" v-for="d in currentDocuments(s)" :key="d.id"><input type="checkbox" v-model="docs" :value="d.id" @change="consent=false">{{d.name}}</label><label class="check consent"><input type="checkbox" v-model="consent">允许将所选资料发送给已配置的模型生成检查清单。</label></details><div class="actions"><span>{{reqs.length}} 条规则已选择</span><button class="primary" @click="start('generate')" :disabled="busy||!!active||!reqs.length||!consent||!docs.length">生成检查清单</button><small class="muted">每批最多3条，可按需求分批生成；内容为检查步骤和预期结果。</small><small class="muted" v-if="!consent">请展开本区域的资料范围，勾选允许处理。</small></div></div></section><details class="card detail" id="workflow-clarify" v-if="s.requirements.length" :open="clarifications.some((q:any)=>q.status==='open')"><summary>澄清与冲突 · {{clarifications.filter((q:any)=>q.status==='open').length}} 项待处理</summary><p class="muted">规则缺失或资料相互矛盾时，登记问题并记录处理决定。</p><label>问题类型<select v-model="clarifyKind"><option value="ambiguity">规则不清</option><option value="conflict">资料冲突</option></select></label><label>需要确认的问题<textarea v-model="clarifyQuestion" rows="2" placeholder="例如，退款期限应按7天还是14天？"></textarea></label><details><summary>选择关联需求（{{clarifyIds.length}} 条）</summary><label class="check" v-for="r in s.requirements.filter((r:any)=>r.status!=='excluded')" :key="r.id"><input type="checkbox" v-model="clarifyIds" :value="r.id">{{r.code}} · {{r.text}}</label></details><button class="secondary" @click="addClarification" :disabled="busy||!!active||!clarifyQuestion.trim()||!clarifyIds.length">登记问题</button><article class="requirement" v-for="q in clarifications.filter((q:any)=>q.status==='open')" :key="q.id"><strong>{{q.kind==='conflict'?'资料冲突':'规则不清'}} · {{q.question}}</strong><p class="muted">{{q.requirement_ids.map((id:string)=>s.requirements.find((r:any)=>r.id===id)?.code).join('、')}}</p><label>处理决定<textarea v-model="clarifyAnswers[q.id]" rows="2" placeholder="填写已确定的规则、采用的资料及理由"></textarea></label><button class="primary" @click="resolveClarification(q)" :disabled="busy||!!active||!clarifyAnswers[q.id]?.trim()">保存处理决定</button></article><details v-if="clarifications.some((q:any)=>q.status==='resolved')"><summary>已处理问题</summary><article v-for="q in clarifications.filter((q:any)=>q.status==='resolved')" :key="q.id"><strong>{{q.question}}</strong><p>{{q.answer}}</p></article></details></details>
<details class="card detail" v-if="s.documents.length"><summary>补充遗漏需求</summary><p class="muted">核对原文发现漏项时，可补充为草稿，再确认后生成用例。</p><label>依据资料<select v-model="manualDoc" @change="manualPage=1"><option value="">选择资料</option><option v-for="d in s.documents" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>{{s.documents.find((d:any)=>d.id===manualDoc)?.format==='pdf'?'依据页码':'依据文本段（内部位置，非物理页码）'}}<input type="number" min="1" :max="s.documents.find((d:any)=>d.id===manualDoc)?.pages.length??1" v-model.number="manualPage"></label><label>引用原文<textarea v-model="manualQuote" rows="2" maxlength="500" placeholder="粘贴对应页中的连续原文"></textarea></label><label>补充的需求<textarea v-model="manualText" rows="2" maxlength="3000"></textarea></label><button class="primary" @click="addManual" :disabled="busy||!!active||!manualDoc||!manualQuote.trim()||!manualText.trim()">保存补充需求</button></details><details class="card detail" v-if="s.requirements.some((r:any)=>r.status==='confirmed')"><summary>数值规则 · 按需确认</summary>
<p class="muted">金额门槛、长度或次数有明确数值时，可按已确认需求登记；生成的输入数值与预期将由程序计算。范围规则包含上下限，其他业务条件需另行检查。</p>
<label>规则名称<input v-model="ruleName" placeholder="例如：满100元减20元"></label>
<div class="inline wrap"><label>规则类型<select v-model="ruleKind"><option value="discount">满额固定抵扣</option><option value="range">数值范围（含上下限）</option></select></label><label>数值含义<input v-model="ruleMetric" placeholder="例如：订单商品总额、文件名长度"></label><label>单位<input v-model="ruleUnit" placeholder="元、字符、次"></label></div>
<div class="inline wrap" v-if="ruleKind==='discount'"><label>使用门槛<input v-model="ruleThreshold" inputmode="decimal" placeholder="例如100"></label><label>抵扣金额<input v-model="ruleDiscount" inputmode="decimal" placeholder="例如20"></label></div>
<div class="inline wrap" v-else><label>包含的下限<input v-model="ruleMin" inputmode="decimal"></label><label>包含的上限<input v-model="ruleMax" inputmode="decimal"></label></div>
<p>关联已确认需求：</p><label class="check" v-for="r in s.requirements.filter((r:any)=>r.status==='confirmed')" :key="r.id"><input type="checkbox" v-model="ruleIds" :value="r.id">{{r.code}} · {{r.text}}</label>
<label class="check consent"><input type="checkbox" v-model="ruleConfirmed">我已按关联需求核对数值、单位和适用条件。</label>
<button class="secondary" @click="addNumericRule" :disabled="busy||!!active||!ruleConfirmed||!ruleIds.length||!ruleName.trim()||!ruleMetric.trim()">确认数值规则</button>
<article class="requirement" v-for="r in s.numeric_rules??[]" :key="r.id"><strong>{{r.name}}</strong><p>{{r.kind==='discount'?`达到${r.threshold}${r.unit}，抵扣${r.discount}${r.unit}`:`${r.metric}范围${r.minimum}至${r.maximum}${r.unit}（含上下限）`}} · {{r.current?'当前有效':r.enabled?'关联需求已变化，需重新确认':'已停用'}}</p><button v-if="r.enabled" class="text-button" @click="disableNumericRule(r.id)" :disabled="busy||!!active">停用规则</button></article>
</details></template>
<template v-if="tab==='用例'"><div class="metrics"><div><strong>{{s.summary.confirmed}}</strong><small>已确认需求</small></div><div><strong>{{s.summary.linked}} / {{s.summary.confirmed}}</strong><small>已有有效关联的需求</small></div><div><strong>{{s.summary.approved}}</strong><small>已审核用例</small></div><div><strong>{{s.summary.review}}</strong><small>待复审用例</small></div></div><section class="card" id="workflow-cases"><div class="toolbar"><select v-model="filter" aria-label="筛选审核状态"><option value="all">全部用例</option><option value="draft">待审核</option><option value="approved">已审核</option><option value="needs_review">待复审</option><option value="rejected">已驳回</option><option value="applied">已应用建议</option></select><div class="actions"><a class="secondary" :href="'/api/v1/caseflow'+path()+'/export?format=xlsx'">导出 Excel</a><a class="secondary" :href="'/api/v1/caseflow'+path()+'/export?format=md'">导出 Markdown</a></div></div><p v-if="!shown.length" class="empty">还没有符合条件的用例。先在需求页确认规则并选择生成。</p><div v-else class="table-wrap"><table><thead><tr><th></th><th>用例</th><th>关联需求</th><th>类型</th><th>审核状态</th><th></th></tr></thead><tbody><tr v-for="c in shown" :key="c.id"><td><input type="checkbox" v-model="cases" :value="c.id" :disabled="!!c.applied_to" :aria-label="'选择'+c.code"></td><td><small>{{c.code}} · 修订 {{c.revision}}</small><strong>{{c.title}}</strong><small v-if="c.grounding">{{groundingLabel(c)}}</small><small v-if="c.replaces_case_id">修改建议 · 对应 {{s.cases.find((x:any)=>x.id===c.replaces_case_id)?.code}}</small><small v-if="c.basis==='suggestion'">补充建议 · 预期需确认</small></td><td>{{c.requirement_ids.map((id:string)=>s.requirements.find((r:any)=>r.id===id)?.code).join('、')}}</td><td>{{c.category}}</td><td><span class="badge" :class="c.status">{{c.applied_to?'已应用':status(c.status)}}</span></td><td><button class="text-button" @click="edit(c.applied_to?s.cases.find((x:any)=>x.id===c.applied_to):c)">{{c.applied_to?'查看原用例':'查看与编辑'}}</button></td></tr></tbody></table></div><div v-if="cases.length" class="review-bar"><span>已选 {{cases.length}} 条</span><input v-model="batchNote" placeholder="审核说明，例如已核对规则与预期结果" aria-label="批量审核说明"><label class="check" v-if="batchNeedsAck"><input type="checkbox" v-model="batchGroundingAck">我已逐项核对所选用例的依据疑点或已修改内容。</label><button class="primary" @click="batch('approved')" :disabled="busy">审核通过</button><button class="secondary" @click="batch('rejected')" :disabled="busy">驳回</button></div><details class="detail"><summary>需求关联情况</summary><p class="muted">有关联不代表测试充分，也不代表已经执行。</p><p v-for="r in s.requirements.filter((r:any)=>r.status==='confirmed')" :key="r.id">{{r.code}} · {{r.text}} <span class="badge">{{s.summary.unlinked.includes(r.id)?'尚无有效关联':'已关联'}}</span></p></details></section><details class="card detail"><summary>执行结果</summary><p class="muted">记录实际执行的结果。旧修订结果保留，不自动算作当前用例通过。</p><div class="inline wrap"><label>测试批次<input v-model="runName"></label><label>用例<select v-model="runCase"><option value="">选择已审核用例</option><option v-for="c in s.cases.filter((c:any)=>c.status==='approved')" :key="c.id" :value="c.id">{{c.code}} {{c.title}}</option></select></label><label>结果<select v-model="runStatus"><option>通过</option><option>失败</option><option>阻塞</option><option>未执行</option></select></label></div><label>执行备注<input v-model="runNote" placeholder="填写实际现象或证据位置"></label><div class="actions"><button class="primary" @click="record" :disabled="busy||!runCase">记录结果</button><a class="secondary" :href="'/api/v1/caseflow'+path()+'/result-template'">下载导入模板</a><label class="upload secondary">导入结果<input type="file" accept=".xlsx,.csv" @change="upload($event,true)" :disabled="busy"></label></div><article class="run" v-for="r in [...s.runs].reverse()" :key="r.id"><strong>{{r.name}}</strong><small>{{date(r.created_at)}}</small><p v-for="(v,i) in r.results" :key="String(i)">{{v.code}} · 修订 {{v.revision}} · {{v.status}} <span class="muted">{{v.current?'当前审核修订':'历史结果'}} · {{v.note}}</span></p></article></details></template>
<template v-if="tab==='变更'">
<section v-if="updatedRules.length" class="card" id="workflow-updated"><div class="heading"><h2>确认修改后的规则</h2><small>{{updatedRules.length}} 条待确认</small></div><p class="muted">在这里核对并确认，不需要切换页面。确认后可继续处理其余变化。</p><article class="requirement" v-for="r in updatedRules" :key="r.id"><strong>{{r.code}} · 待确认</strong><textarea :aria-label="r.code+'更新内容'" v-model="drafts[r.id]!.text" rows="3"></textarea><div class="citations"><button v-for="(q,i) in r.citations" :key="String(i)" @click="citation(q)">查看原文 · {{citationLabel(q)}}</button></div><p v-for="q in r.questions" :key="q">{{q}}</p><label v-if="r.questions.length">已确定的补充<input v-model="drafts[r.id]!.answer"></label><div class="actions"><button class="primary" @click="saveReq(r,'confirmed')" :disabled="busy||!!active">确认这条规则</button><button class="secondary" @click="saveReq(r,'draft')" :disabled="busy||!!active">保存，稍后确认</button></div></article></section>
<ChangeReview :pending="pending" :requirements="s.requirements" :selections="changes" :busy="busy||!!active" @select="(id,target)=>changes[id]=target?[target]:[]" @decide="decide" @source="citation"/>
<section class="card" v-if="s.cases.some((c:any)=>c.status==='needs_review')"><div class="heading"><h2>需要更新的检查项</h2></div><p class="muted">规则修改后，旧内容会保留。核对新规则后再修改并审核。</p><article class="requirement" v-for="c in s.cases.filter((c:any)=>c.status==='needs_review')" :key="c.id"><strong>{{c.code}} · {{c.title}}</strong><p class="muted">关联规则：{{c.requirement_ids.map((id:string)=>s.requirements.find((r:any)=>r.id===id)?.code).join('、')}}</p><button class="secondary" @click="edit(c)">核对并修改</button></article></section>
<details class="card detail"><summary>已处理记录</summary><p v-for="c in s.changes.filter((c:any)=>c.status!=='pending')" :key="c.id">{{kind(c.kind)}} · {{c.proposed?.text??'移除原需求'}} · {{status(c.status)}}</p></details><details class="card detail"><summary>需求与用例历史</summary><article v-for="entry in s.history.map((h:any,i:number)=>({h,i})).reverse()" :key="entry.i"><p>{{entry.h.value.code}} · 修订 {{entry.h.revision}} → {{historyAfter(entry.h,entry.i)?.revision}} · {{date(entry.h.at)}}</p><div v-for="d in fieldDiff(entry.h.value,historyAfter(entry.h,entry.i))" :key="d.label" class="field-diff"><strong>{{d.label}}</strong><div class="compare"><div><small>修改前</small><pre>{{d.before}}</pre></div><div><small>修改后</small><pre>{{d.after}}</pre></div></div></div><p v-if="!fieldDiff(entry.h.value,historyAfter(entry.h,entry.i)).length" class="muted">内容相同，保留此时记录。</p></article><p v-if="!s.history.length" class="muted">修改后将在这里保留历史。</p></details><details class="card detail"><summary>导出记录</summary><p v-for="e in [...s.exports].reverse()" :key="e.id">{{date(e.at)}} · {{e.format==='xlsx'?'Excel':'Markdown'}} · {{e.rows.length}} 条用例 <span class="muted">资料记录 {{e.project_revision}}</span></p><p v-if="!s.exports.length" class="muted">导出后将在这里保留交付记录。</p></details></template>
<details v-if="tasks.length" class="card detail"><summary>处理记录</summary><div class="task-record" v-for="t in tasks" :key="t.id">{{date(t.created_at)}} · {{({extract:'整理需求',generate:'生成用例',index:'整理资料索引',review:'检查依据'} as Record<string,string>)[t.kind]}} · {{status(t.status)}} <span class="error-text">{{t.error}}</span><button v-if="['failed','blocked'].includes(t.status)" class="text-button" @click="resumeTask(t)" :disabled="busy||!!active">继续已保存任务</button><details v-if="t.result?.partial"><summary>查看已整理部分</summary><pre>{{JSON.stringify(t.result.extracted,null,2)}}</pre></details></div><details v-if="trace.length"><summary>查看本次资料查阅过程</summary><pre>{{JSON.stringify(trace,null,2)}}</pre></details></details></template>
<footer>CaseFlow<span>从需求整理到用例交付</span></footer></div></main>
<DocumentReader v-if="source&&p" :project-id="p.id" :document-id="source.documentId" :evidence-id="source.evidenceId" :legacy="source.legacy" @close="closeSource" @located="located"/>
<div v-if="editor" class="overlay" @click.self="editor=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="编辑用例"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><div class="heading"><h2>{{editor.code}} · 用例详情</h2><button class="close" @click="editor=null" aria-label="关闭用例">×</button></div><details v-if="editor.replaces_case_id" class="detail" open><summary>与原用例比较</summary><p class="muted">{{s.cases.find((x:any)=>x.id===editor.replaces_case_id)?.code}} · 建议基于修订 {{editor.replaces_case_revision??'未记录'}}，当前修订 {{s.cases.find((x:any)=>x.id===editor.replaces_case_id)?.revision}}</p><div v-for="d in fieldDiff(s.cases.find((x:any)=>x.id===editor.replaces_case_id),{...editor,steps:steps.split('\n')})" :key="d.label" class="field-diff"><strong>{{d.label}}</strong><div class="compare"><div><small>原内容</small><pre>{{d.before}}</pre></div><div><small>修改建议</small><pre>{{d.after}}</pre></div></div></div></details><label>标题<input v-model="editor.title"></label><label>前置条件<textarea v-model="editor.preconditions" rows="2"></textarea></label><label>输入数据<textarea v-model="editor.data" rows="2"></textarea></label><label>操作步骤（每行一步）<textarea v-model="steps" rows="4"></textarea></label><label>预期结果<textarea v-model="editor.expected" rows="3"></textarea></label><p class="message" v-if="editor.basis==='suggestion'">这是补充建议，请核实预期结果再审核。</p><GroundingReport :row="editor" :changed="editorDirty" :requirements="s.requirements"/><details class="detail" :open="!consent&&!editor.grounding"><summary>检查使用的资料 · {{docs.length}} 份已选择</summary><label class="check" v-for="d in currentDocuments(s)" :key="d.id"><input type="checkbox" v-model="docs" :value="d.id" @change="consent=false">{{d.name}}</label><label class="check consent"><input type="checkbox" v-model="consent">允许将所选资料发送给已配置的模型进行检查。</label></details><p v-if="editorDirty" class="muted">内容有修改，请先保存草稿，再检查已保存内容。</p><p v-else-if="!consent" class="muted">请展开上方资料范围并勾选允许处理，然后开始检查。</p><button class="secondary" @click="start('review',editor)" :disabled="busy||!!active||editorDirty||!consent||!docs.length">检查已保存内容</button><div class="citations"><button v-for="(q,i) in editor.citations" :key="String(i)" @click="citation(q)">查看依据：{{q.quote.slice(0,45)}}…</button></div><label class="check consent" v-if="editorNeedsAck"><input type="checkbox" v-model="groundingAck">我已逐项核对依据疑点或修改后的内容，并在审核说明中记录判断。</label><label>审核说明<input v-model="review" placeholder="说明核对了哪些规则和预期结果"></label><div class="actions"><button v-if="editor.replaces_case_id" class="primary" @click="applyProposal" :disabled="busy">应用到原用例</button><button v-else class="primary" @click="saveCase('approved')" :disabled="busy">保存并审核通过</button><button class="secondary" @click="saveCase('draft')" :disabled="busy">保存草稿</button><button class="text-button" @click="saveCase('rejected')" :disabled="busy">驳回</button></div></section></div>
<div v-if="settingsVisible" class="overlay" @click.self="settingsVisible=false"><section class="dialog" role="dialog" aria-modal="true" aria-label="设置"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success">{{notice}}</p><div class="heading"><h2>模型设置</h2><button class="close" @click="settingsVisible=false" aria-label="关闭设置">×</button></div><template v-if="settings"><p class="message">{{settingsInfo?.reason}}</p><label>连接方式<select v-model="settings.mode"><option value="free">百炼免费模型</option><option value="compatible">兼容模型服务</option></select></label><label>模型名称<input v-model="settings.model"></label><label class="check"><input type="checkbox" v-model="settings.enabled">启用此模型处理已授权资料</label><details class="detail"><summary>连接与请求限制</summary><label>服务地址<input v-model="settings.base_url"></label><label>密钥环境变量名<input v-model="settings.key_env"></label><p class="muted">密钥在服务端配置，不在页面填写。免费模型需有效额度核验。</p><label>每日请求上限<input type="number" v-model.number="settings.daily_limit" min="1" max="200"></label><label>单次输出上限<input type="number" v-model.number="settings.max_output" min="256" max="2048"></label><p class="muted">今日已预留 {{settingsInfo?.used_today}} 次请求；次数不是金额上限。</p></details><button class="primary" @click="saveSettings" :disabled="busy">保存设置</button></template></section></div>
</div>
</template>
<style>
body{margin:0}.cf{font:14px/1.65 "Segoe UI","Microsoft YaHei",sans-serif;color:#253832;background:#f5f7f6;min-height:100vh}.cf *{box-sizing:border-box}.cf button,.cf input,.cf textarea,.cf select{font:inherit}.cf button{cursor:pointer}.cf button:disabled{opacity:.5;cursor:not-allowed}.cf aside{position:fixed;inset:0 auto 0 0;width:236px;background:#112e29;color:#eaf4ef;padding:28px 22px;display:flex;flex-direction:column}.cf .brand{display:flex;gap:12px;align-items:center;background:none;border:0;color:white;font-size:24px;font-weight:650;padding:0;text-align:left}.cf .brand b{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#bddbc9;color:#183e31;font-size:25px}.cf .brand small{display:block;font-size:11px;color:#9cbbb0;font-weight:400;margin-top:3px}.cf .home{margin:38px 0 16px;background:none;border:0;color:#c4dbd0;text-align:left;padding:12px 10px}.cf .project-name{font-size:12px;color:#8fae9e;border-top:1px solid #315044;padding-top:22px;overflow-wrap:anywhere}.cf nav{display:grid;gap:7px;margin-top:10px}.cf nav button{display:flex;justify-content:space-between;border:0;background:none;color:#b5cec1;text-align:left;padding:12px 16px;border-radius:7px}.cf nav button.active{background:#294b3e;color:white}.cf nav small{background:#496753;border-radius:10px;padding:0 6px}.cf .aside-bottom{margin-top:auto;display:grid;gap:16px;color:#8fae9e;font-size:11px}.cf .aside-bottom button{color:#c4dbd0;background:none;border:0;text-align:left;padding:8px 10px}.cf main{margin-left:236px;min-width:0}.cf header{height:72px;background:white;border-bottom:1px solid #e0e7e2;padding:0 42px;display:flex;align-items:center;justify-content:space-between;color:#52685d;font-size:13px}.cf .local{color:#5b8270;background:#edf5ee;padding:5px 10px;border-radius:5px}.cf .content{max-width:1280px;padding:36px 42px;margin:auto}.cf .title{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.cf h1{font-size:28px;letter-spacing:-.6px;margin:4px 0 8px;font-weight:650;line-height:1.4}.cf .title p{color:#7c8a81;margin:0}.cf .eyebrow{font-size:10px;letter-spacing:2px;color:#5a8d71;font-weight:650}.cf h2{font-size:16px;margin:0}.cf .card{background:#fff;border:1px solid #e0e7e2;border-radius:12px;padding:25px;margin-bottom:22px;min-width:0}.cf .card p{overflow-wrap:anywhere}.cf .heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:17px}.cf .heading>small{color:#8b998f;font-size:12px}.cf .create{display:flex;align-items:center;justify-content:space-between;gap:25px}.cf .create p{font-size:12px;margin:5px 0}.cf .inline{display:flex;align-items:flex-end;gap:14px}.cf .inline>input{min-width:260px}.cf .wrap{flex-wrap:wrap}.cf .wrap>label{flex:1;min-width:160px}.cf label{display:block;margin:16px 0 8px;font-size:13px;color:#5b6c62}.cf input:not([type=checkbox]):not([type=file]),.cf select,.cf textarea{display:block;width:100%;padding:10px 12px;border:1px solid #dce5de;border-radius:7px;background:#fcfdfc;color:#293f33;margin-top:5px;line-height:1.6}.cf textarea{resize:vertical}.cf input[type=checkbox]{width:16px;height:16px;accent-color:#28634d;flex-shrink:0;margin:4px 0 0}.cf :focus-visible{outline:3px solid #a9cbb8;outline-offset:2px}.cf .primary,.cf .secondary{display:inline-flex;align-items:center;justify-content:center;padding:10px 16px;border-radius:7px;white-space:nowrap;font-weight:500;font-size:13px;line-height:1.6;text-decoration:none;margin:0}.cf .primary{background:#245d46;color:white;border:1px solid #245d46}.cf .primary:hover{background:#194a36}.cf .secondary{background:white;color:#51685a;border:1px solid #dbe5dd}.cf .upload{cursor:pointer}.cf .upload input{display:none}.cf .actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:16px}.cf .text-button{border:0;background:none;color:#39795b;padding:6px 0;font-size:13px}.cf .muted{font-size:12px;color:#8a998f}.cf .empty{padding:30px 15px;text-align:center;color:#8a998f;font-size:13px}.cf .project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:24px}.cf .project{position:relative;text-align:left;margin:0;color:#253832}.cf .project:hover{border-color:#83ac92;box-shadow:0 5px 18px #183d2510}.cf .project h3{font-size:17px;margin:17px 0 8px}.cf .project p{font-size:12px;color:#718779}.cf .project small{font-size:11px;color:#95a298}.cf .folder{font-size:24px;color:#5a896b}.cf .arrow{position:absolute;right:20px;top:22px;color:#86a38f}.cf .examples{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cf .examples button{border:1px dashed #cddbd0;border-radius:10px;text-align:left;padding:18px 20px;background:#f9fbf9;color:#45654f;font-weight:600}.cf .examples small{display:block;color:#91a194;font-weight:400;margin-top:6px}.cf .document{display:flex;justify-content:space-between;gap:15px;align-items:center;border-top:1px solid #edf1ed;padding:12px 0}.cf .check{display:flex;align-items:flex-start;gap:10px;margin:0}.cf .check small{display:block;color:#93a096;font-size:11px;margin-top:3px}.cf .consent{background:#f1f7f1;border-radius:8px;padding:12px;margin-top:16px;font-size:12px}.cf .requirement{padding:22px 0;border-top:1px solid #e7ede7}.cf .item-title{display:flex;gap:12px;align-items:center;margin-bottom:12px}.cf .badge{display:inline-block;background:#eef2ee;color:#7a897b;font-size:11px;border-radius:5px;padding:3px 8px;white-space:nowrap}.cf .badge.confirmed,.cf .badge.approved{color:#36714b;background:#eaf4eb}.cf .badge.needs_review,.cf .badge.draft{color:#9a7938;background:#fbf3e2}.cf .badge.rejected,.cf .badge.excluded{color:#a07770;background:#f7eeeb}.cf .questions{background:#fffaf0;padding:14px;border-radius:8px;font-size:13px;color:#92773c;margin-top:14px}.cf .questions p{margin:5px 0}.cf .citations{display:flex;flex-wrap:wrap;gap:12px;margin:10px 0}.cf .citations button{background:none;border:0;padding:0;color:#508567;font-size:12px;text-align:left}.cf .bottom{border-top:1px solid #e7ede7;padding-top:18px}.cf .metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.cf .metrics>div{background:#fff;border:1px solid #e2e8e2;border-radius:9px;padding:18px 22px}.cf .metrics strong{font-size:26px;display:block;color:#31553d}.cf .metrics small{color:#8d9c8e}.cf .toolbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.cf .toolbar>select{width:auto;margin:0}.cf .toolbar .actions{margin:0}.cf .table-wrap{overflow-x:auto}.cf table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}.cf th{font-size:11px;font-weight:500;color:#8b9b8c;background:#f7f9f7;padding:12px;white-space:nowrap}.cf td{padding:17px 12px;border-bottom:1px solid #edf1ec;vertical-align:middle}.cf td strong,.cf td small{display:block}.cf td small{font-size:10px;color:#92a091;margin-bottom:3px}.cf td strong{font-weight:500;min-width:140px;max-width:360px;overflow-wrap:anywhere}.cf .review-bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:16px;background:#f4f8f3;margin-top:18px;border-radius:8px}.cf .review-bar input{flex:1;min-width:200px}.cf .detail{margin-top:22px}.cf summary{color:#526f58;font-size:13px;cursor:pointer;padding:7px 0}.cf pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:60vh;overflow:auto;background:#f5f8f4;padding:18px;border:1px solid #e7ede5;border-radius:8px;font:13px/1.9 Consolas,"Microsoft YaHei",monospace}.cf .compare{display:grid;grid-template-columns:1fr 1fr;gap:20px}.cf .compare>div{padding:15px;background:#f7f9f6;border-radius:8px}.cf .compare small{color:#91a08e}.cf .compare .check{margin-top:10px}.cf .change{padding:20px 0;border-top:1px solid #e8ede6}.cf .run{padding:15px 0;border-top:1px solid #e8ede6}.cf .run small{display:block;color:#93a08f}.cf .message{padding:12px 16px;border:1px solid #e5dcc3;background:#fdf9ee;color:#897745;border-radius:8px;font-size:13px;margin:0 0 20px}.cf .error{border-color:#e7c7bf;background:#fff2ee;color:#a05842}.cf .error button{float:right;border:0;background:none;color:inherit;font-size:18px}.cf .success{border-color:#cbdcc8;background:#f0f7ed;color:#4d7748}.cf .error-text{color:#a0684a}.cf .progress{padding:13px 17px;background:#edf5ee;color:#5c805f;border-radius:8px;margin-bottom:20px;font-size:13px}.cf footer{display:flex;justify-content:space-between;color:#a0ad9f;font-size:11px;margin-top:40px;padding:20px 0;border-top:1px solid #e1e8df}.cf .overlay{position:fixed;inset:0;background:#152c2366;display:grid;place-items:center;padding:24px;z-index:100}.cf .dialog{background:white;width:min(780px,100%);max-height:90vh;overflow:auto;padding:28px;border-radius:12px;box-shadow:0 20px 80px #133c2626}.cf .close{background:#f2f5f0;border:0;width:32px;height:32px;border-radius:6px;font-size:22px;color:#789072}
